mapper.select:
SELECT id, merchant_id, sku_id, available_qty, reserved_qty, version, create_time, update_time
FROM inventory
WHERE merchant_id = #{merchantId}
  AND sku_id = #{skuId}

mapper.update:
UPDATE inventory
SET available_qty = #{availableQty},
    reserved_qty  = #{reservedQty},
    version       = version + 1,
    update_time   = CURRENT_TIMESTAMP
WHERE merchant_id = #{merchantId}
  AND sku_id = #{skuId}
  AND version = #{version}

mapper.select:
SELECT id, merchant_id, sku_id, available_qty, reserved_qty, version, create_time, update_time
FROM inventory
WHERE merchant_id = #{merchantId}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM inventory
WHERE merchant_id = #{merchantId}
